import {mountAntioxidantEpilogue} from './antioxidant-epilogue.js';
import {predictionMarkup,mountPrediction,hasPrediction,clearPrediction} from './prediction.js';
import {mountEverydayRedox} from './everyday-redox.js';
import {mountForgePrep} from './forge-prep.js';
import {upgradeInteractiveLab} from './lab-upgrade.js';
import {lessons,materialCases,freshState,restoreState,isReady,migrateLegacy,migrateEight} from './journey-cards.js';
import {mountBurn} from './hands-on-burn.js';
import {mountNarrative} from './narrative-labs.js';
const $=id=>document.getElementById(id),storageKey='lost-forge-hands-on-7-v3';
let raw={},canStore=true,current=1,prepCount=0,lifeCount=0;try{raw=JSON.parse(localStorage.getItem(storageKey)||'{}');}catch{canStore=false;}
let legacy={};try{legacy=JSON.parse(localStorage.getItem('lost-forge-hands-on-9-v1')||'{}');}catch{}
let previousEight={};try{previousEight=JSON.parse(localStorage.getItem('lost-forge-hands-on-8-v2')||'{}');}catch{}
const states=lessons.map(c=>raw[c.id]?restoreState(c,raw[c.id]):Object.keys(previousEight).length?migrateEight(c,previousEight):migrateLegacy(c,legacy)),cards=[];
const displayNumber=c=>c.id===1?'序章':String(c.id+1).padStart(2,'0');
const mastered=c=>isReady(c,states[c.id-1])&&states[c.id-1].answer===c.quiz.answer;
function save(){try{localStorage.setItem(storageKey,JSON.stringify(Object.fromEntries(lessons.map(c=>[c.id,states[c.id-1]]))));}catch{canStore=false;}route();}
function route(){const n=lessons.filter(mastered).length;$('top-progress').textContent=(n+prepCount+lifeCount)+' / '+(lessons.length+4);$('mastery-label').textContent='探索 '+(n+lifeCount)+' / 8 · 試煉 '+prepCount+' / 3';$('mastery-progress').max=lessons.length+4;$('mastery-progress').value=n+prepCount+lifeCount;let act='';$('route').innerHTML=lessons.map(c=>{const heading=act!==c.act?'<p class="route-act">'+c.act+'</p>':'';act=c.act;return (c.id===2?'<a class="prep-route" href="#forge-prep" '+(current==='prep'?'aria-current="step"':'')+'><span>01</span><span>煉鐵前的工坊試煉</span><i>'+(prepCount===3?'✓':'○')+'</i></a><a class="life-route" href="#everyday-redox" '+(current==='life'?'aria-current="step"':'')+'><span>02</span><span>日常生活中的氧化還原</span><i>'+(lifeCount?'✓':'○')+'</i></a>':'')+heading+`<a href="#card-${c.id}" ${current===c.id?'aria-current="step"':''} class="${mastered(c)?'mastered':''}"><span>${displayNumber(c)}</span><span>${c.title}</span><i aria-label="${mastered(c)?'已掌握':'待探索'}">${mastered(c)?'✓':isReady(c,states[c.id-1])?'◉':'○'}</i></a>`;}).join('');$('storage-note').textContent=canStore?'觀察與作答進度會自動保存。':'本次可正常操作，但瀏覽器無法保存進度。';}
function mount(c){const article=document.createElement('article');article.id='card-'+c.id;article.dataset.card=c.id;article.className='exploration-card hands-card';article.tabIndex=-1;article.setAttribute('aria-labelledby',article.id+'-title');$('lesson').append(article);cards.push(article);let s=states[c.id-1],epoch=0,timers=new Set(),cleanup=[],predictionControl;const predictionId='main-'+c.id;
 const find=selector=>article.querySelector(selector),has=k=>s.evidence.includes(k);
 function cancel(){epoch++;for(const t of timers)clearTimeout(t);timers.clear();for(const f of cleanup)f();cleanup=[];}
 function delay(fn,ms){const token=epoch;const t=setTimeout(()=>{timers.delete(t);if(token===epoch&&article.isConnected)fn();},matchMedia('(prefers-reduced-motion:reduce)').matches?Math.min(ms,80):ms);timers.add(t);}
 function record(k){if(!hasPrediction(predictionId)||!c.required.includes(k))return;if(!has(k))s.evidence.push(k);sync();save();}
 function notice(t){find('.observation-status').textContent=t;}
 function renderLab(){cancel();notice('先讀取場景，再直接拖動物件，看看發生什麼。');const context={s,has,record,notice,delay,setCase:(key,autoLoad,spoonOrigin=null)=>{s.selected=key;s.autoLoad=autoLoad;s.spoonOrigin=spoonOrigin;renderLab();save();},onCleanup:f=>cleanup.push(f)};if(['combustion','metals','nonmetals'].includes(c.type))mountBurn(find('.interactive-lab'),c,context);else mountNarrative(find('.interactive-lab'),c,context);cleanup.push(upgradeInteractiveLab(find('.interactive-lab'),c,context));find('.case-rack')?.querySelectorAll('[data-case]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.case===s.selected)));}
 function render(){article.innerHTML=`<header class="chapter-header"><div class="chapter-kicker"><span>${c.act}</span><div class="chapter-actions"><span>${c.day} · ${c.id===1?'序章':displayNumber(c)+' / '+(lessons.length+1)}</span><button type="button" class="card-reset" data-reset aria-label="重設${displayNumber(c)}：${c.title}">↺ 重設本卡</button></div></div><h2 id="${article.id}-title">${c.title}</h2><p class="core-question">${c.question}</p></header><div class="chapter-body"><div class="story-scene-intro ${c.id===1?'with-forge-scene':''}">${c.id===1?$('locked-forge-scene').innerHTML:''}<div class="story-scene-copy"><p class="opening">${c.opening}</p><div class="story-dialogue" aria-label="小葵與阿公的對話">${c.dialogue.map(([who,line])=>`<div class="story-speech story-speech--${who}"><span class="story-portrait story-portrait--${who}" data-expression="${c.portraits[who]}" aria-hidden="true"></span><p><b>${who==='kui'?'小葵':'阿公'}</b>${line}</p></div>`).join('')}</div></div></div><div class="forge-purpose"><b>這次的任務</b><p>${c.purpose}</p></div>${predictionMarkup(predictionId)}<div data-prediction-activity inert><div class="interaction-instruction"><span class="hand-icon">↔</span><p>${c.task}</p></div>${materialCases[c.type]&&!['combustion','redox','steel'].includes(c.type)?`<div class="case-rack" role="group" aria-label="選擇代表案例">${materialCases[c.type].map(([key,label])=>`<button data-case="${key}" aria-pressed="${s.selected===key}"><span class="case-symbol">${({CO:'C',ZnCu:'Zn',CuZn:'Cu',alone:'CuO',carbon:'C',wrought:'Fe',pig:'Fe–C',steel:'鋼',normal:'①',stress:'②'})[key]||key}</span><span>${label}</span></button>`).join('')}</div>`:''}${c.type==='combustion'?'<button class="studio-enter" data-enter-studio>進入實驗台，完整查看樣本與器材 ↘</button>':''}<div class="interactive-lab"></div><p class="observation-status" aria-live="polite"></p></div><div data-prediction-review hidden></div><div class="evidence-panel"><span class="step-label">已留下的線索</span><ul class="evidence-list"></ul></div><p class="keyboard-help">滑鼠按住物件拖動；也可用 Tab 選取物件，Enter 拿起／放下，方向鍵移動。礦石直接用方向鍵轉動。</p><section class="discovery" hidden><span class="step-label">把觀察連成解釋</span><h3>${c.conceptTitle}</h3>${c.id===1?'':`<p class="observation-note"><b>你找到的現象</b>${c.finding}</p>`}<ul class="concept-points">${c.points.map(p=>`<li>${p}</li>`).join('')}</ul>${c.id===1?'':`<div class="reaction-equation">${c.equation.replaceAll('\n','<br>')}</div>`}<p class="forge-takeaway"><b>小葵的鍛造筆記</b>${c.benefit}</p><button class="primary" data-understood>我理解了，試一題 <span>→</span></button></section><section class="practice" hidden aria-labelledby="${article.id}-quiz"><span class="step-label">小試身手</span><h3 id="${article.id}-quiz">${c.quiz.question}</h3><div class="quiz-options">${c.quiz.options.map((text,i)=>`<button class="quiz-option" data-answer="${i}" aria-pressed="false"><span>${String.fromCharCode(65+i)}</span>${text}</button>`).join('')}</div><p class="feedback" aria-live="polite"></p></section><div class="chapter-bridge" hidden><span class="step-label">${c.id===1?'工坊試煉｜先認識氧化':c.id===lessons.length?'尾聲｜回家的路':'接著探索 '+String(c.id+2).padStart(2,'0')+'｜'+lessons[c.id].title}</span><p>${c.bridge}</p></div></div><footer class="chapter-footer">${c.id>1?`<a class="previous" href="${c.id===2?'#everyday-redox':'#card-'+(c.id-1)}">← 上一張</a>`:''}<button class="text-button" data-reset>重設本卡</button><a class="next" href="${c.id===1?'#forge-prep':c.id===lessons.length?'#epilogue-antioxidants':'#card-'+(c.id+1)}">${c.id===1?'先認識氧化與氧的轉移':c.id===lessons.length?'回家後，小葵又有新問題':'帶著線索往下走'} <b>→</b></a></footer>`;
 find('.case-rack')?.addEventListener('click',e=>{const b=e.target.closest('[data-case]');if(!b||!hasPrediction(predictionId))return;s.selected=b.dataset.case;s.tab='burn';renderLab();save();});
 find('[data-enter-studio]')?.addEventListener('click',()=>{find('.combustion-studio').scrollIntoView({block:'start',behavior:'instant'});find('.combustion-studio').focus({preventScroll:true});});
 article.querySelectorAll('[data-reset]').forEach(b=>b.addEventListener('click',()=>{cancel();clearPrediction(predictionId);s=freshState(c);states[c.id-1]=s;render();save();notice('已重設本卡，可以重新操作。');find('.chapter-header [data-reset]').focus({preventScroll:true});}));
 find('[data-understood]').addEventListener('click',()=>{if(!isReady(c,s))return;s.quizOpen=true;sync();save();find('.practice').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion:reduce)').matches?'auto':'smooth',block:'center'});});
 find('.quiz-options').addEventListener('click',e=>{const b=e.target.closest('[data-answer]');if(!b||!s.quizOpen||!isReady(c,s))return;s.answer=Number(b.dataset.answer);sync();save();});renderLab();predictionControl=mountPrediction(find('[data-prediction-host]'),predictionId,{activity:find('[data-prediction-activity]'),review:find('[data-prediction-review]'),observed:s.evidence.length>0,onStart:()=>{sync();}});sync();}
 function sync(){const ready=isReady(c,s),unlocked=hasPrediction(predictionId);predictionControl?.setObserved(s.evidence.length>0);find('.evidence-list').innerHTML=c.required.map((k,i)=>`<li class="${has(k)?'done':''}"><span>${has(k)?'✓':'○'}</span>${c.labels[i]}</li>`).join('');find('.discovery').hidden=!(ready&&unlocked);find('.practice').hidden=!(ready&&s.quizOpen&&unlocked);find('[data-understood]').hidden=s.quizOpen;find('.chapter-bridge').hidden=!ready;find('.feedback').textContent=s.answer===null?'':(s.answer===c.quiz.answer?'✓ 答對了。':'再想一想。')+c.quiz.explanations[s.answer]+(['combustion','redox','furnace','steel','rust'].includes(c.type)&&s.answer!==null&&s.answer!==c.quiz.answer?' 正確答案：'+String.fromCharCode(65+c.quiz.answer)+'，'+c.quiz.options[c.quiz.answer]+'。':'');find('.feedback').className='feedback '+(s.answer===null?'':s.answer===c.quiz.answer?'correct':'retry');find('.quiz-options').querySelectorAll('[data-answer]').forEach(b=>{const selected=Number(b.dataset.answer)===s.answer;b.setAttribute('aria-pressed',String(selected));b.classList.toggle('right',selected&&s.answer===c.quiz.answer);b.classList.toggle('wrong',selected&&s.answer!==c.quiz.answer);});}
 render();window.addEventListener('pagehide',cancel);
}

lessons.forEach(mount);
$('card-6').before($('forged-sword-scene').content.cloneNode(true));
const prep=document.createElement('article');prep.id='forge-prep';prep.className='exploration-card';prep.tabIndex=-1;prep.dataset.card='prep';cards.splice(1,0,prep);prep.setAttribute('aria-labelledby','forge-prep-title');$('card-2').before(prep);prep.addEventListener('prep-progress',e=>{prepCount=e.detail;route();});mountForgePrep(prep);
const life=document.createElement('article');life.id='everyday-redox';life.className='exploration-card';life.tabIndex=-1;life.dataset.card='life';life.setAttribute('aria-labelledby','everyday-redox-title');cards.splice(2,0,life);$('card-2').before(life);life.addEventListener('life-progress',e=>{lifeCount=e.detail;route();});mountEverydayRedox(life);route();
const epilogue=mountAntioxidantEpilogue($('lesson'));

function activate(id){if(current===id)return;current=id;for(const a of $('route').querySelectorAll('a'))a.hash===(id==='prep'?'#forge-prep':id==='life'?'#everyday-redox':'#card-'+id)?a.setAttribute('aria-current','step'):a.removeAttribute('aria-current');}
window.addEventListener('hashchange',()=>{if(location.hash==='#epilogue-antioxidants'){activate(7);epilogue.focus({preventScroll:true});return;}if(location.hash==='#everyday-redox'){activate('life');life.focus({preventScroll:true});return;}if(location.hash==='#forge-prep'){activate('prep');prep.focus({preventScroll:true});return;}const id=Number(location.hash.replace('#card-',''));if(lessons.some(c=>c.id===id)){activate(id);$('card-'+id).focus({preventScroll:true});}});
let frame=false;window.addEventListener('scroll',()=>{if(frame)return;frame=true;requestAnimationFrame(()=>{frame=false;let active=cards[0];for(const card of cards){if(card.getBoundingClientRect().top>innerHeight*.25)break;active=card;}activate(['prep','life'].includes(active.dataset.card)?active.dataset.card:Number(active.dataset.card));});},{passive:true});
requestAnimationFrame(()=>{const target=document.querySelector(/^#(?:card-[1-9]|forge-prep|everyday-redox|epilogue-antioxidants)$/.test(location.hash)?location.hash:'#card-1');if(location.hash&&target){target.scrollIntoView({block:'start',behavior:'instant'});if(target.dataset.card)activate(['prep','life'].includes(target.dataset.card)?target.dataset.card:Number(target.dataset.card));}});
